css:
#tongsci1-3-2-2-3-catch .ct-body { grid-template-columns: 1040px minmax(0, 1fr); }
#tongsci1-3-2-2-3-catch .head.split .ct-ask { font-size: 38px; white-space: normal; max-width: 640px; text-align: right; line-height: 1.15; margin: 0; }
#tongsci1-3-2-2-3-catch .ct-body { grid-template-columns: 1040px minmax(0, 1fr); }
.ct-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #eef1f6; }
.ct-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
.ct-stage canvas.holding { cursor: grabbing; }
.ct-stage .now-chip { left: auto; right: 16px; top: 22px; }
.ct-panel { gap: 10px; }
.ct-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.6em; flex: none; }
.ct-out b { color: var(--accent); }
.ct-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 17px/1.3 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
.ct-tab th { font: 700 17px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; }
.ct-tab th:first-child { width: 17%; }
.ct-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 3px 6px; text-align: center; }
.ct-tab td[data-ct] { font-family: var(--f-mono); font-size: 15px; background: color-mix(in srgb, var(--hl) 25%, #fff); }
.ct-tab td b { color: var(--accent); }
.ct-calc { margin: 0; font-size: 17px; line-height: 1.45; flex: none; border-left: 5px solid var(--accent); padding: 4px 10px; background: var(--paper-2); }
section.ex.u-done .ct-calc { display: none; }

